  var BOX = { w: 578, h: 743 };           // logo box, native units
  var LAYERS = [{"name":"frame","x":188,"y":48,"w":347,"h":696,"b64":""},{"name":"swirl","x":501,"y":657,"w":78,"h":79,"b64":""},{"name":"swash","x":-1,"y":357,"w":293,"h":109,"b64":""},{"name":"stem","x":345,"y":74,"w":68,"h":198,"b64":""},{"name":"leaf","x":278,"y":73,"w":72,"h":170,"b64":""},{"name":"flowerA","x":338,"y":-1,"w":78,"h":80,"b64":""},{"name":"flowerB","x":404,"y":64,"w":71,"h":72,"b64":""},{"name":"the1","x":294,"y":291,"w":53,"h":118,"b64":""},{"name":"the2","x":343,"y":282,"w":94,"h":128,"b64":""},{"name":"the3","x":431,"y":320,"w":82,"h":89,"b64":""},{"name":"paper1","x":154,"y":431,"w":89,"h":123,"b64":""},{"name":"paper2","x":239,"y":430,"w":88,"h":90,"b64":""},{"name":"paper3","x":319,"y":431,"w":90,"h":123,"b64":""},{"name":"paper4","x":406,"y":429,"w":82,"h":91,"b64":""},{"name":"paper5","x":482,"y":431,"w":86,"h":88,"b64":""},{"name":"story1","x":176,"y":568,"w":75,"h":90,"b64":""},{"name":"story2","x":245,"y":541,"w":52,"h":117,"b64":""},{"name":"story3","x":293,"y":568,"w":87,"h":90,"b64":""},{"name":"story4","x":374,"y":568,"w":86,"h":89,"b64":""},{"name":"story5","x":453,"y":569,"w":88,"h":94,"b64":""}];                       // [{name,x,y,w,h,b64}]
  var NOISE = "";
